/* Self-contained rand/srand/srand48/drand48 for OS-9/68k. * * nobs needs all four. It cannot use LIB/rand.r or LIB/unix.l, because both * of those also export randint(), which nobs defines itself in shuf.c -- the * link dies on duplicate symbols. clib.l has no rand()/srand() at all, and no * library on this system has the 48-bit generators. So provide the lot here. * * Park-Miller minimal standard LCG; 31-bit, period 2^31-2. */static long _seed = 1L;void srand(s)unsigned s;{    _seed = (long) s;    if (_seed == 0L) _seed = 1L;}int rand(){    long hi, lo;    hi = _seed / 127773L;    lo = _seed % 127773L;    _seed = 16807L * lo - 2836L * hi;    if (_seed <= 0L) _seed += 2147483647L;    return (int) (_seed & 0x7fff);}void srand48(seed)long seed;{    srand((unsigned) seed);}double drand48(){    return (double) rand() / 32768.0;}